-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9319, 24, 'Kommunale Finanzausstattung über den Finanzausgleich erhöhen und Mindestausstattung sichern (Land)', 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'belegt', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'land', null, true, 'blind'),
  (9320, 24, 'Kommunalfinanzierung verlässlich und aufgabengerecht ausrichten, ohne zusätzliche Mittel zu nennen (Land)', 'Eine aufgabengerechtere, transparentere Verteilung kann Belastungen besser abbilden und ist rechtlich einfach; ohne zusätzliche Mittel verschiebt sie aber vor allem Geld zwischen Kommunen und verbessert die Gesamtlage kaum.', 'offen', null, 'land', null, true, 'blind'),
  (9321, 24, 'Finanzierungssystem und eigene Einnahmen der Bezirke eines Stadtstaats neu ordnen (Land)', 'Mehr finanzielle Eigenständigkeit kann die Handlungsfähigkeit der Bezirke stärken; die Wirkung hängt von der Gesamtsumme ab, und eigene Einnahmen oder Klagerechte erfordern aufwendige Verfassungs- und Gesetzesänderungen.', 'offen', null, 'land', null, true, 'blind'),
  (9322, 24, 'Konnexität: vom Land übertragene Aufgaben vollständig gegenfinanzieren (Land)', 'Verhindert neue ungedeckte Lasten und ist in den meisten Landesverfassungen schon angelegt; bestehende Defizite und vom Bund verursachte Sozialausgaben bleiben unberührt, die Wirkung ist empirisch kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9323, 24, 'Landesprogramm zur Entschuldung von Kommunen (Altschulden, Kassenkredite) (Land)', 'Länderprogramme haben Kassenkredite gestoppt und Haushalte ausgeglichen; zugleich kürzten Teilnehmerkommunen Investitionen und erhöhten Steuern, und die Programme binden hohe Landesmittel über viele Jahre.', 'gemischt', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'land', null, true, 'blind'),
  (9324, 24, 'Altschuldenlösung von Bund und Ländern für überschuldete Kommunen (Bund)', 'Entschuldung schafft Spielraum, Länderprogramme zeigen gestoppte Kassenkredite, aber auch Investitionskürzungen bei Auflagen; der Bund kann sich finanziell beteiligen, braucht aber die Länder und ggf. eine Verfassungsänderung.', 'gemischt', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'bund', null, true, 'blind'),
  (9325, 24, 'Höheren Anteil der Kommunen an Einkommen- und Umsatzsteuer auf Bundesebene anstreben (Land)', 'Ein höherer Steueranteil stärkt die Einnahmebasis dauerhaft; das Land kann das nur über Bundesrat und Bundesgesetz erreichen, und die Verteilung begünstigt eher steuerstarke Kommunen.', 'offen', null, 'land', null, true, 'blind'),
  (9326, 24, 'Förderprogramme für Kommunen in pauschale Zuweisungen überführen und Förderverfahren vereinfachen (Land)', 'Kommunen nennen aufwendige Anträge, Nachweise und Personalmangel als Investitionshemmnis; Pauschalen und Verzicht auf Eigenanteile helfen gerade schwachen Kommunen. Dagegen: kein zusätzliches Geld, weniger Steuerung, Wirkung kaum evaluiert.', 'offen', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'land', null, true, 'blind'),
  (9327, 24, 'Förderprogramme des Bundes für Kommunen bündeln und Antragsverfahren vereinfachen (Bund)', 'Vereinfachte Anträge entlasten Verwaltungen, die über Förderbürokratie klagen; die Finanzlage selbst ändert sich dadurch kaum, und die Wirkung solcher Bündelungen ist wenig untersucht.', 'offen', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'bund', null, true, 'blind'),
  (9328, 24, 'Planungs-, Genehmigungs- und Vergabeverfahren beschleunigen und digitalisieren (Land)', 'Fristen, Digitalisierung und einfachere Vergabe können Verwaltungen entlasten; bisherige Beschleunigungsgesetze brachten nur begrenzte Erfolge, weil lange Verfahren oft am materiellen Recht und fehlendem Personal liegen.', 'gemischt', 'https://trid.trb.org/View/2427394', 'land', null, true, 'blind'),
  (9329, 24, 'Fachliche Unterstützung der Kommunen durch das Land bei Bauprojekten und Bauleitplanung (Land)', 'Vorlagen und Beratung können kleine, personalschwache Bauverwaltungen entlasten und sind leicht umsetzbar; sie ersetzen weder Personal noch Geld, die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9330, 24, 'Interkommunale Zusammenarbeit erleichtern und fördern (Land)', 'Kooperation gilt als Mittel, Personal und Kosten zu bündeln, und ist weit verbreitet; belastbare Studien zu Einsparungen fehlen für Deutschland weitgehend, die Finanzlage ändert sich nur am Rand.', 'offen', 'https://ideas.repec.org/a/zbw/iwhwiw/iwh-1-16-4.html', 'land', null, true, 'blind'),
  (9331, 24, 'Hochschul- und Studienangebote in den Regionen erhalten und ausbauen (Land)', 'Neue Hochschulen erhöhen nachweislich Studierendenzahl und Anteil Hochqualifizierter in der Region; in wenig dynamischen Regionen wandern Absolventen aber oft ab, und Ausbau kostet viel und dauert Jahre.', 'gemischt', 'https://www.zew.de/PU83481', 'land', null, true, 'blind'),
  (9332, 24, 'Absolventen durch Karriereberatung und Vernetzung mit regionalen Arbeitgebern binden (Land)', 'Kontakte zu regionalen Arbeitgebern während des Studiums können den Verbleib erleichtern und sind günstig umsetzbar; ohne passende Stellen bleibt die Wirkung begrenzt und ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9333, 24, 'Prämien, Stipendien oder Darlehenserlass gegen Verbleib im Land nach Ausbildung oder Studium (Land)', 'Bindungsprämien sind einfach einzuführen; Studien zu Verpflichtungsprogrammen finden nur schwache Belege für dauerhaften Verbleib, viele brechen ab oder ziehen nach der Bindungsfrist weg, Mitnahmeeffekte sind wahrscheinlich.', 'gemischt', 'https://rrh.org.au/journal/article/2459', 'land', null, true, 'blind'),
  (9334, 24, 'Rückkehr- und Willkommensagenturen für Abgewanderte und Zuziehende (Land)', 'Rückkehrinitiativen in ländlichen Regionen erhöhen nachweislich die Rückwanderung, besonders bei mittleren und höheren Einkommen; sie wirken auf bereits Abgewanderte und ersetzen fehlende Stellen nicht.', 'belegt', 'https://ideas.repec.org/a/oup/jecgeo/v24y2024i5p759-784..html', 'land', null, true, 'blind'),
  (9335, 24, 'Eigenheimförderung und zinsgünstige Kredite für Familien, die in der Region bleiben oder zurückkehren (Land)', 'Wohneigentumsförderung wirkt in ländlichen Regionen als Bleibeanreiz; Evaluationen ähnlicher Zuschüsse zeigen aber erhebliche Mitnahmeeffekte und Vorteile für einkommensstarke Haushalte, die Kosten sind hoch.', 'gemischt', 'https://www.diw.de/de/diw_01.c.593685.de/publikationen/diw_aktuell/2018_0014/baukindergeld__einkommensstarke_haushalte_profitieren_in_besonderem_masse.html', 'land', null, true, 'blind'),
  (9336, 24, 'Familienbezogene Geldleistungen des Landes zur Förderung von Geburten (Land)', 'Geldleistungen bei Geburt erhöhen die Geburtenzahl in Studien messbar, aber nur um wenige Prozent; an Alterung und Abwanderung ändern sie wenig, und dauerhafte Landesleistungen sind teuer.', 'belegt', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'land', null, true, 'blind'),
  (9337, 24, 'Steuerliche Entlastung oder Kredite mit Teilerlass für Familien zur Geburtenförderung (Bund)', 'Finanzielle Anreize für Kinder zeigen in Studien einen beständigen, aber kleinen Effekt auf Geburten; Steuerreformen dieser Art sind teuer und begünstigen oft höhere Einkommen, Alterung bleibt weitgehend unberührt.', 'belegt', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'bund', null, true, 'blind'),
  (9338, 24, 'Finanzielle Unterstützung von Kinderwunschbehandlungen (Land)', 'Zuschüsse erhöhen die Nutzung der Reproduktionsmedizin und ermöglichen einzelnen Paaren Kinder; Studien finden aber kaum Effekte auf die Geburtenrate insgesamt, weil sich Geburten eher ins höhere Alter verschieben.', 'gemischt', 'https://ifstudies.org/blog/mandating-insurance-coverage-for-ivf-will-not-boost-fertility', 'land', null, true, 'blind'),
  (9339, 24, 'Umlagefinanzierter Ausbildungsfonds, in den nicht ausbildende Betriebe einzahlen (Bund)', 'Die Pflege-Ausbildungsumlage erhöhte die Zahl der Auszubildenden; eine Studie aus Québec fand dagegen keine Wirkung auf das Ausbildungsniveau. Mehr Plätze lösen zudem nicht die Passungsprobleme bei unbesetzten Stellen.', 'gemischt', 'https://dspace-test.bibb.de/items/035ea543-8cab-4e72-a7a6-b31107ba1a2d/full', 'bund', null, true, 'blind'),
  (9340, 24, 'Berufsorientierung und Jugendberufsagenturen stärken und abstimmen (Bund)', 'Junge Menschen mit durchgehendem Beratungskontakt münden weit häufiger in Ausbildung, was an der Passung ansetzt; der Zusammenhang ist aber nicht kausal belegt, und Jugendberufsagenturen hängen von Ländern und Kommunen ab.', 'gemischt', 'https://www.bibb.de/dienst/nlt/de/newsletter/newsletter_bibbaktuell_2025_09.php', 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 24 and id not in (9319, 9320, 9321, 9322, 9323, 9324, 9325, 9326, 9327, 9328, 9329, 9330, 9331, 9332, 9333, 9334, 9335, 9336, 9337, 9338, 9339, 9340);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9341, 24, 11, null, 'Berufsorientierung in allen Schulformen strukturieren und bestehende Maßnahmen bundesweit und regional aufeinander abstimmen', '{2403}', 9340, 2, 2, null, 'Junge Menschen mit durchgehendem Beratungskontakt münden weit häufiger in Ausbildung, was an der Passung ansetzt; der Zusammenhang ist aber nicht kausal belegt, und Jugendberufsagenturen hängen von Ländern und Kommunen ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=67', 'https://www.bibb.de/dienst/nlt/de/newsletter/newsletter_bibbaktuell_2025_09.php', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9342, 24, 11, null, 'Kommunal relevante Bundesförderprogramme zusammenfassen, online bündeln und Antragsverfahren sowie Nachweispflichten vereinfachen', '{2404}', 9327, 1, 3, null, 'Vereinfachte Anträge entlasten Verwaltungen, die über Förderbürokratie klagen; die Finanzlage selbst ändert sich dadurch kaum, und die Wirkung solcher Bündelungen ist wenig untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9343, 24, 11, null, 'Konnexität: Wer Aufgaben für Länder und Kommunen veranlasst oder ausweitet, muss sie finanzieren', '{2404}', null, 1, 2, null, 'Wenn der Bund neue Leistungen selbst finanziert, entstehen Ländern und Kommunen keine neuen Lasten; als Grundsatz ohne Gesetzesänderung ist das unverbindlich, bestehende Lücken bleiben.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=76', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9344, 24, 11, 'MV', 'Programm „Stay in MV“ mit regionalen Netzwerken, Mentoring und Stipendien mit Mindestverbleib im Land, um Studierende zu halten', '{2401}', 9333, 1, 3, null, 'Bindungsprämien sind einfach einzuführen; Studien zu Verpflichtungsprogrammen finden nur schwache Belege für dauerhaften Verbleib, viele brechen ab oder ziehen nach der Bindungsfrist weg, Mitnahmeeffekte sind wahrscheinlich.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=69', 'https://rrh.org.au/journal/article/2459', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9345, 24, 11, 'MV', 'Staatliche Hochschule in Schwerin schaffen, um junge Menschen nach dem Schulabschluss in der Region zu halten', '{2401}', 9331, 2, 2, null, 'Neue Hochschulen erhöhen nachweislich Studierendenzahl und Anteil Hochqualifizierter in der Region; in wenig dynamischen Regionen wandern Absolventen aber oft ab, und Ausbau kostet viel und dauert Jahre.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=65', 'https://www.zew.de/PU83481', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9346, 24, 11, 'MV', 'Finanzausgleichsgesetz novellieren, Infrastrukturpauschale deutlich anheben und Investitionsmittel mehrjährig bereitstellen, auch für finanzschwache Kommunen', '{2404}', 9319, 2, 2, null, 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=41', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9347, 24, 11, 'MV', 'Entschuldungsprogramme für hoch verschuldete Kommunen fortführen und weiterentwickeln', '{2404}', 9323, 2, 2, null, 'Länderprogramme haben Kassenkredite gestoppt und Haushalte ausgeglichen; zugleich kürzten Teilnehmerkommunen Investitionen und erhöhten Steuern, und die Programme binden hohe Landesmittel über viele Jahre.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=42', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9348, 24, 11, 'MV', 'Landesbeschleunigungsgesetz mit verbindlichen Fristen und digitalisierten Verfahren für schnellere Planung und Genehmigung', '{2404}', 9328, 1, 3, null, 'Fristen, Digitalisierung und einfachere Vergabe können Verwaltungen entlasten; bisherige Beschleunigungsgesetze brachten nur begrenzte Erfolge, weil lange Verfahren oft am materiellen Recht und fehlendem Personal liegen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=104', 'https://trid.trb.org/View/2427394', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9349, 24, 11, 'MV', 'Standardisierte Vorlagen für Bauprojekte stellen, um Kommunen bei der Bauverwaltung fachlich zu unterstützen', '{2404}', 9329, 1, 3, null, 'Vorlagen und Beratung können kleine, personalschwache Bauverwaltungen entlasten und sind leicht umsetzbar; sie ersetzen weder Personal noch Geld, die Wirkung ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=113', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9350, 24, 11, 'ST', 'Kommunalen Finanzausgleich in neuem Gesetz ab 2027 nach Gutachten umsetzen, mit Mindestausstattung und Ausgleich struktureller Finanzschwäche', '{2404}', 9319, 2, 2, null, 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=79', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9351, 24, 11, 'ST', 'Unterstützungsfonds für kleine Kommunen in Haushaltskonsolidierung für kleinere Investitionen', '{2404}', null, 1, 3, null, 'Ein kleiner Fonds kann verhindern, dass Kommunen in Konsolidierung jede Investition streichen, ein bekanntes Problem solcher Programme; der Umfang ist gering, die Wirkung kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=10', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9352, 24, 11, 'ST', 'Genehmigungs- und Vergabeverfahren vollständig digitalisieren, Genehmigungsfiktion einführen, Stichproben statt Nachweisprüfung', '{2404}', 9328, 1, 3, null, 'Fristen, Digitalisierung und einfachere Vergabe können Verwaltungen entlasten; bisherige Beschleunigungsgesetze brachten nur begrenzte Erfolge, weil lange Verfahren oft am materiellen Recht und fehlendem Personal liegen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=55', 'https://trid.trb.org/View/2427394', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9353, 24, 11, 'ST', 'Gemeinsame digitale Basisdienste und interkommunale Lösungen für Kommunen, um Vergabe zu beschleunigen und Verwaltungen zu entlasten', '{2404}', 9328, 1, 3, null, 'Fristen, Digitalisierung und einfachere Vergabe können Verwaltungen entlasten; bisherige Beschleunigungsgesetze brachten nur begrenzte Erfolge, weil lange Verfahren oft am materiellen Recht und fehlendem Personal liegen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=55', 'https://trid.trb.org/View/2427394', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9354, 24, 11, 'ST', 'Förderverfahren für Kommunen vereinfachen, mehr Pauschalzahlungen und Experimentierklauseln, interkommunale Zusammenarbeit fördern', '{2404}', 9326, 2, 3, null, 'Kommunen nennen aufwendige Anträge, Nachweise und Personalmangel als Investitionshemmnis; Pauschalen und Verzicht auf Eigenanteile helfen gerade schwachen Kommunen. Dagegen: kein zusätzliches Geld, weniger Steuerung, Wirkung kaum evaluiert.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=10', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9355, 24, 11, 'ST', 'Paare mit unerfülltem Kinderwunsch weiter finanziell unterstützen', '{2402}', 9338, 1, 3, null, 'Zuschüsse erhöhen die Nutzung der Reproduktionsmedizin und ermöglichen einzelnen Paaren Kinder; Studien finden aber kaum Effekte auf die Geburtenrate insgesamt, weil sich Geburten eher ins höhere Alter verschieben.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=31', 'https://ifstudies.org/blog/mandating-insurance-coverage-for-ivf-will-not-boost-fertility', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9356, 24, 11, 'ST', 'Hochschulen bauen Bindungsinstrumente für internationale Studierende auf und erleichtern den Übergang in den regionalen Arbeitsmarkt', '{2401}', 9332, 1, 3, null, 'Kontakte zu regionalen Arbeitgebern während des Studiums können den Verbleib erleichtern und sind günstig umsetzbar; ohne passende Stellen bleibt die Wirkung begrenzt und ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=76', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9357, 24, 12, null, 'Branchenbezogene Umlagen bzw. Fonds, wo unterhalb des Bedarfs ausgebildet wird, und mehr Ausbildungsverantwortung der Unternehmen.', '{2403}', 9339, 2, 2, null, 'Die Pflege-Ausbildungsumlage erhöhte die Zahl der Auszubildenden; eine Studie aus Québec fand dagegen keine Wirkung auf das Ausbildungsniveau. Mehr Plätze lösen zudem nicht die Passungsprobleme bei unbesetzten Stellen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', 'https://dspace-test.bibb.de/items/035ea543-8cab-4e72-a7a6-b31107ba1a2d/full', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9358, 24, 12, null, 'Ausbildungsgarantie fortführen und Jugendberufsagenturen weiter stärken.', '{2403}', null, 2, 3, null, 'Die bestehende Ausbildungsgarantie mit außerbetrieblichen Plätzen fängt Jugendliche ohne Betrieb auf und ist gesetzlich verankert; außerbetriebliche Ausbildung führt nicht immer in Beschäftigung und löst unbesetzte Stellen nicht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9359, 24, 12, null, 'Lösung für die Altschulden der Kommunen, auch unter Berücksichtigung ostdeutscher Kommunen.', '{2404}', 9324, 2, 2, null, 'Entschuldung schafft Spielraum, Länderprogramme zeigen gestoppte Kassenkredite, aber auch Investitionskürzungen bei Auflagen; der Bund kann sich finanziell beteiligen, braucht aber die Länder und ggf. eine Verfassungsänderung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9360, 24, 12, null, 'Förderprogramme für Kommunen deutlich vereinfachen und entbürokratisieren.', '{2404}', 9327, 1, 3, null, 'Vereinfachte Anträge entlasten Verwaltungen, die über Förderbürokratie klagen; die Finanzlage selbst ändert sich dadurch kaum, und die Wirkung solcher Bündelungen ist wenig untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9361, 24, 12, 'MV', 'Alle Hochschulstandorte im Land erhalten und weiterentwickeln, um junge Menschen im Land zu halten.', '{2401}', 9331, 2, 2, null, 'Neue Hochschulen erhöhen nachweislich Studierendenzahl und Anteil Hochqualifizierter in der Region; in wenig dynamischen Regionen wandern Absolventen aber oft ab, und Ausbau kostet viel und dauert Jahre.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=71', 'https://www.zew.de/PU83481', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9362, 24, 12, 'MV', 'Landeswerbemaßnahmen bündeln und mit attraktiven Lebensbedingungen verknüpfen, um Fachkräfte an das Land zu binden.', '{2401}', null, 1, 3, null, 'Gebündelte Standortwerbung ist günstig und schnell umsetzbar; ohne bessere Stellen- oder Ausbildungsangebote ändert Werbung an den Gründen für Abwanderung wenig, belastbare Wirkungsnachweise fehlen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=21', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9363, 24, 12, 'MV', 'Kommunen verlässlich finanzieren, Mehrbelastungen ausgleichen (Konnexität) und Entschuldung und Konsolidierung weiter unterstützen.', '{2404}', 9320, 1, 3, null, 'Eine aufgabengerechtere, transparentere Verteilung kann Belastungen besser abbilden und ist rechtlich einfach; ohne zusätzliche Mittel verschiebt sie aber vor allem Geld zwischen Kommunen und verbessert die Gesamtlage kaum.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=51', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9364, 24, 12, 'ST', 'Landesbehörden in Mittelzentren und ländlichen Regionen ansiedeln, um Abwanderung entgegenzuwirken', '{2401}', null, 1, 2, null, 'Öffentliche Stellen ziehen private Beschäftigung nach sich (etwa 55 private je 100 öffentliche Stellen beim Umzug nach Berlin); Verlagerungen betreffen aber nur wenige Stellen, dauern Jahre und kosten viel.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=59', 'https://openaccess.city.ac.uk/id/eprint/22234', 'belegt', '2026-10-08', false, true, 'blind'),
  (9365, 24, 12, 'ST', 'Familien, die in ihrer Heimat bleiben wollen, werden unterstützt, auch durch zinslose Kredite', '{2401}', 9335, 1, 2, null, 'Wohneigentumsförderung wirkt in ländlichen Regionen als Bleibeanreiz; Evaluationen ähnlicher Zuschüsse zeigen aber erhebliche Mitnahmeeffekte und Vorteile für einkommensstarke Haushalte, die Kosten sind hoch.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=44', 'https://www.diw.de/de/diw_01.c.593685.de/publikationen/diw_aktuell/2018_0014/baukindergeld__einkommensstarke_haushalte_profitieren_in_besonderem_masse.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9366, 24, 12, 'ST', 'Bedarfsgerechter kommunaler Finanzausgleich, der Aufgaben und Abschreibungen abbildet; Bundeszuweisungen nicht anrechnen', '{2404}', 9319, 2, 2, null, 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=60', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9367, 24, 12, 'ST', 'Höhere Anteile der Kommunen an Umsatz- und Einkommensteuer, Gewerbesteuer erhalten', '{2404}', 9325, 2, 1, null, 'Ein höherer Steueranteil stärkt die Einnahmebasis dauerhaft; das Land kann das nur über Bundesrat und Bundesgesetz erreichen, und die Verteilung begünstigt eher steuerstarke Kommunen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=49', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9368, 24, 12, 'ST', 'Planungs- und Genehmigungsverfahren beschleunigen, Vergaberecht vereinfachen', '{2404}', 9328, 1, 3, null, 'Fristen, Digitalisierung und einfachere Vergabe können Verwaltungen entlasten; bisherige Beschleunigungsgesetze brachten nur begrenzte Erfolge, weil lange Verfahren oft am materiellen Recht und fehlendem Personal liegen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=44', 'https://trid.trb.org/View/2427394', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9369, 24, 12, 'ST', 'Interkommunale Zusammenarbeit und Verwaltungskooperationen fördern, Doppelprüfungen abbauen', '{2404}', 9330, 1, 3, null, 'Kooperation gilt als Mittel, Personal und Kosten zu bündeln, und ist weit verbreitet; belastbare Studien zu Einsparungen fehlen für Deutschland weitgehend, die Finanzlage ändert sich nur am Rand.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=49', 'https://ideas.repec.org/a/zbw/iwhwiw/iwh-1-16-4.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9370, 24, 13, null, 'Von Bund und Ländern finanzierter Altschuldenfonds für finanzschwache Kommunen nach Strukturwandel', '{2404}', 9324, 2, 2, null, 'Entschuldung schafft Spielraum, Länderprogramme zeigen gestoppte Kassenkredite, aber auch Investitionskürzungen bei Auflagen; der Bund kann sich finanziell beteiligen, braucht aber die Länder und ggf. eine Verfassungsänderung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=108', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9371, 24, 13, null, 'Kommunen erhalten direkt mehr Geld und mehr ungebundene Mittel statt vieler Förderprogramme', '{2404}', null, 2, 2, null, 'Ungebundene Mittel erhöhen nachweislich die Ausgaben der Kommunen und mindern Förderbürokratie; der Bund kann Kommunen aber nur auf Umwegen (etwa Umsatzsteueranteil) direkt finanzieren, die Höhe ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=109', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9372, 24, 13, null, 'Solidarische Ausbildungsumlage soll die Ausbildungsbereitschaft kleiner und mittlerer Betriebe fördern', '{2403}', 9339, 2, 2, null, 'Die Pflege-Ausbildungsumlage erhöhte die Zahl der Auszubildenden; eine Studie aus Québec fand dagegen keine Wirkung auf das Ausbildungsniveau. Mehr Plätze lösen zudem nicht die Passungsprobleme bei unbesetzten Stellen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', 'https://dspace-test.bibb.de/items/035ea543-8cab-4e72-a7a6-b31107ba1a2d/full', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9373, 24, 13, null, 'Flächendeckende Jugendberufsagenturen als Anlaufstelle für Berufsorientierung und Ausbildungsplatzsuche', '{2403}', 9340, 2, 2, null, 'Junge Menschen mit durchgehendem Beratungskontakt münden weit häufiger in Ausbildung, was an der Passung ansetzt; der Zusammenhang ist aber nicht kausal belegt, und Jugendberufsagenturen hängen von Ländern und Kommunen ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=79', 'https://www.bibb.de/dienst/nlt/de/newsletter/newsletter_bibbaktuell_2025_09.php', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9374, 24, 13, null, 'Auszubildendenwerke mit Wohnheimen nach dem Vorbild der Studierendenwerke fördern', '{2403}', null, 1, 3, null, 'Wohnheime erleichtern Auszubildenden den Umzug zu einem passenden Ausbildungsplatz und setzen an regionaler Passung an; der Bund fördert junges Wohnen bereits, die Wirkung auf die Besetzung von Stellen ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9375, 24, 13, 'BE', 'Reproduktionsmedizin ausbauen und Beratung erweitern, um Menschen mit unerfülltem Kinderwunsch zu unterstützen.', '{2402}', 9338, 1, 3, null, 'Zuschüsse erhöhen die Nutzung der Reproduktionsmedizin und ermöglichen einzelnen Paaren Kinder; Studien finden aber kaum Effekte auf die Geburtenrate insgesamt, weil sich Geburten eher ins höhere Alter verschieben.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=206', 'https://ifstudies.org/blog/mandating-insurance-coverage-for-ivf-will-not-boost-fertility', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9376, 24, 13, 'MV', 'Welcome Center und One-Stop-Agencies für Zuzug und Berufsrückkehrende ausbauen, um Fachkräfte im Land zu halten', '{2401}', 9334, 2, 3, null, 'Rückkehrinitiativen in ländlichen Regionen erhöhen nachweislich die Rückwanderung, besonders bei mittleren und höheren Einkommen; sie wirken auf bereits Abgewanderte und ersetzen fehlende Stellen nicht.', 'https://gruene-mv.de/?wpdmdl=33772#page=30', 'https://ideas.repec.org/a/oup/jecgeo/v24y2024i5p759-784..html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9377, 24, 13, 'MV', 'Hochschulen und Fachschulen stärker mit regionalen Unternehmen vernetzen, damit Absolventinnen und Absolventen im Land bleiben', '{2401}', 9332, 1, 3, null, 'Kontakte zu regionalen Arbeitgebern während des Studiums können den Verbleib erleichtern und sind günstig umsetzbar; ohne passende Stellen bleibt die Wirkung begrenzt und ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=30', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9378, 24, 13, 'MV', 'Zinsfreies Startdarlehen für Azubis, das nach einem Jahr Arbeit im Land entfällt', '{2401}', 9333, 1, 3, null, 'Bindungsprämien sind einfach einzuführen; Studien zu Verpflichtungsprogrammen finden nur schwache Belege für dauerhaften Verbleib, viele brechen ab oder ziehen nach der Bindungsfrist weg, Mitnahmeeffekte sind wahrscheinlich.', 'https://gruene-mv.de/?wpdmdl=33772#page=31', 'https://rrh.org.au/journal/article/2459', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9379, 24, 13, 'MV', 'Das Land als Studienstandort stärken, mit Landesprogramm für internationale Studiengänge und Hochschulmarketing, um mehr junge Menschen zu gewinnen', '{2401}', 9331, 2, 2, null, 'Neue Hochschulen erhöhen nachweislich Studierendenzahl und Anteil Hochqualifizierter in der Region; in wenig dynamischen Regionen wandern Absolventen aber oft ab, und Ausbau kostet viel und dauert Jahre.', 'https://gruene-mv.de/?wpdmdl=33772#page=38', 'https://www.zew.de/PU83481', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9380, 24, 13, 'MV', 'Jugendkultur gegen Abwanderung fördern, mit Stabsstelle in der Staatskanzlei und ausreichender Finanzierung', '{2401}', null, 1, 3, null, 'Jugendkultur kann die Lebensqualität junger Menschen vor Ort erhöhen und ist mit überschaubaren Mitteln umsetzbar; die Hauptgründe für Abwanderung sind aber Ausbildung, Studium und Beruf, die Wirkung ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=64', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9381, 24, 13, 'MV', 'Finanzielle Handlungsfähigkeit der Kommunen durch mehr direkte Zuweisungen statt Förderprogramme und echte Konnexität stärken', '{2404}', 9326, 2, 3, null, 'Kommunen nennen aufwendige Anträge, Nachweise und Personalmangel als Investitionshemmnis; Pauschalen und Verzicht auf Eigenanteile helfen gerade schwachen Kommunen. Dagegen: kein zusätzliches Geld, weniger Steuerung, Wirkung kaum evaluiert.', 'https://gruene-mv.de/?wpdmdl=33772#page=104', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9382, 24, 13, 'ST', 'Reform der Kommunalfinanzierung mit Flächenfaktor, kommunaler Grundsicherung und verlässlicher Finanzausstattung; Altschuldenfonds für überschuldete Kommunen.', '{2404}', 9319, 2, 2, null, 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=97', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9383, 24, 14, null, 'Berufsorientierung und Jugendberufsagenturen stärken, ein berufliches Orientierungsjahr schaffen und Azubi-Stipendien ausbauen.', '{2403}', 9340, 2, 2, null, 'Junge Menschen mit durchgehendem Beratungskontakt münden weit häufiger in Ausbildung, was an der Passung ansetzt; der Zusammenhang ist aber nicht kausal belegt, und Jugendberufsagenturen hängen von Ländern und Kommunen ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', 'https://www.bibb.de/dienst/nlt/de/newsletter/newsletter_bibbaktuell_2025_09.php', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9384, 24, 14, 'BE', 'Grund- und Gewerbesteuer langfristig durch kommunalen Zuschlag mit eigenem Hebesatzrecht auf Körperschaft- und Einkommensteuer ersetzen, ggf. höherer Kommunalanteil an der Umsatzsteuer.', '{2404}', null, 1, 1, null, 'Ein Zuschlag mit Hebesatzrecht könnte kommunale Einnahmen stetiger machen; die Umstellung ist nur über Bund und Grundgesetzänderung möglich und bringt ohne höheren Umsatzsteueranteil kaum mehr Geld.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=50', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9385, 24, 14, 'MV', 'Kommunalen Finanzausgleich transparenter und einfacher machen und stärker an den tatsächlichen Aufgaben und Belastungen ausrichten.', '{2404}', 9320, 1, 3, null, 'Eine aufgabengerechtere, transparentere Verteilung kann Belastungen besser abbilden und ist rechtlich einfach; ohne zusätzliche Mittel verschiebt sie aber vor allem Geld zwischen Kommunen und verbessert die Gesamtlage kaum.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=77', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9386, 24, 14, 'MV', 'Bedürfnisse des ländlichen Raums bei der Finanzausstattung der Kommunen stärker berücksichtigen.', '{2404}', 9320, 1, 3, null, 'Eine aufgabengerechtere, transparentere Verteilung kann Belastungen besser abbilden und ist rechtlich einfach; ohne zusätzliche Mittel verschiebt sie aber vor allem Geld zwischen Kommunen und verbessert die Gesamtlage kaum.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=79', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9387, 24, 14, 'MV', 'Freiwillige Zusammenarbeit von Kommunen fördern, etwa durch gemeinsame Verwaltungseinheiten.', '{2404}', 9330, 1, 3, null, 'Kooperation gilt als Mittel, Personal und Kosten zu bündeln, und ist weit verbreitet; belastbare Studien zu Einsparungen fehlen für Deutschland weitgehend, die Finanzlage ändert sich nur am Rand.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=80', 'https://ideas.repec.org/a/zbw/iwhwiw/iwh-1-16-4.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9388, 24, 14, 'MV', 'Juristischen Examensstudiengang an der Universität Rostock wieder eröffnen, um Abwanderung junger Talente zu verhindern.', '{2401}', 9331, 2, 2, null, 'Neue Hochschulen erhöhen nachweislich Studierendenzahl und Anteil Hochqualifizierter in der Region; in wenig dynamischen Regionen wandern Absolventen aber oft ab, und Ausbau kostet viel und dauert Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=139', 'https://www.zew.de/PU83481', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9389, 24, 14, 'ST', 'Bestehende Hochschulstandorte im ländlichen Raum gezielt unterstützen und strukturell fördern.', '{2401}', 9331, 2, 2, null, 'Neue Hochschulen erhöhen nachweislich Studierendenzahl und Anteil Hochqualifizierter in der Region; in wenig dynamischen Regionen wandern Absolventen aber oft ab, und Ausbau kostet viel und dauert Jahre.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=33', 'https://www.zew.de/PU83481', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9390, 24, 14, 'ST', 'Zuzug aus Metropolräumen durch bezahlbare Wohnungen, schnelles Internet und Coworking-Angebote gewinnen.', '{2402}', null, 1, 2, null, 'Bezahlbares Wohnen, Internet und Coworking können Zuzug aus Ballungsräumen erleichtern; die Maßnahme bleibt allgemein, und wie viele Menschen dadurch tatsächlich zuziehen, ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=58', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9391, 24, 14, 'ST', 'Einnahmebasis der Kommunen stärken: höherer Anteil an Einkommen- und Umsatzsteuer, Gewerbesteuer sichern.', '{2404}', 9325, 2, 1, null, 'Ein höherer Steueranteil stärkt die Einnahmebasis dauerhaft; das Land kann das nur über Bundesrat und Bundesgesetz erreichen, und die Verteilung begünstigt eher steuerstarke Kommunen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=50', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9392, 24, 14, 'ST', 'Fördermittel möglichst in pauschale Investitionszuweisungen überführen, um Kommunen von Förderlogik und Bürokratie zu entlasten.', '{2404}', 9326, 2, 3, null, 'Kommunen nennen aufwendige Anträge, Nachweise und Personalmangel als Investitionshemmnis; Pauschalen und Verzicht auf Eigenanteile helfen gerade schwachen Kommunen. Dagegen: kein zusätzliches Geld, weniger Steuerung, Wirkung kaum evaluiert.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=50', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9393, 24, 14, 'ST', 'Planungs- und Genehmigungsverfahren beschleunigen, kommunale Verantwortung stärken und interkommunale Kooperation erleichtern.', '{2404}', 9328, 1, 3, null, 'Fristen, Digitalisierung und einfachere Vergabe können Verwaltungen entlasten; bisherige Beschleunigungsgesetze brachten nur begrenzte Erfolge, weil lange Verfahren oft am materiellen Recht und fehlendem Personal liegen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=58', 'https://trid.trb.org/View/2427394', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9394, 24, 15, null, 'Rückzahlung von Rentenbeiträgen oder Freistellung von künftigen Zahlungen bei jeder Geburt, um Familien zu entlasten und mehr Kinder zu ermöglichen.', '{2402}', null, 1, 1, null, 'Hohe Geldleistungen je Geburt erhöhen Geburten in Studien messbar, aber begrenzt; 20.000 Euro je Kind kosten jährlich zweistellige Milliardenbeträge, die Finanzierung der Rentenversicherung ist ungeklärt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=148', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'belegt', '2026-10-08', false, true, 'blind'),
  (9395, 24, 15, null, 'Ehe-Start-Kredit für junge Paare bei Familiengründung, der mit jedem Kind teilweise erlassen wird.', '{2402}', 9337, 1, 2, null, 'Finanzielle Anreize für Kinder zeigen in Studien einen beständigen, aber kleinen Effekt auf Geburten; Steuerreformen dieser Art sind teuer und begünstigen oft höhere Einkommen, Alterung bleibt weitgehend unberührt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=149', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'belegt', '2026-10-08', false, true, 'blind'),
  (9396, 24, 15, null, 'Familiensplitting statt Ehegattensplitting, um Familien mit Kindern steuerlich zu entlasten und Anreiz für mehr Kinder zu schaffen.', '{2402}', 9337, 1, 2, null, 'Finanzielle Anreize für Kinder zeigen in Studien einen beständigen, aber kleinen Effekt auf Geburten; Steuerreformen dieser Art sind teuer und begünstigen oft höhere Einkommen, Alterung bleibt weitgehend unberührt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=60', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'belegt', '2026-10-08', false, true, 'blind'),
  (9397, 24, 15, 'BE', 'Steuerliches Familiensplitting zusätzlich zum Kindergeld einführen, damit junge Menschen früher Kinder bekommen können.', '{2402}', null, 1, 1, null, 'Finanzielle Entlastung von Familien wirkt in Studien nur schwach auf Geburten; ein Familiensplitting ist Bundessteuerrecht, das Land kann es nur über den Bundesrat anstoßen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=58', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'belegt', '2026-10-08', false, true, 'blind'),
  (9398, 24, 15, 'BE', 'Landeserziehungsgeld für U3-Kinder in Höhe der vergleichbaren Kosten eines Kita-Platzes einführen.', '{2402}', 9336, 1, 2, null, 'Geldleistungen bei Geburt erhöhen die Geburtenzahl in Studien messbar, aber nur um wenige Prozent; an Alterung und Abwanderung ändern sie wenig, und dauerhafte Landesleistungen sind teuer.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'belegt', '2026-10-08', false, true, 'blind'),
  (9399, 24, 15, 'BE', 'Bezirke durch eigene Einnahmequellen und ein eigenes Klagerecht in ihrer Rechtsstellung stärken.', '{2404}', 9321, 1, 2, null, 'Mehr finanzielle Eigenständigkeit kann die Handlungsfähigkeit der Bezirke stärken; die Wirkung hängt von der Gesamtsumme ab, und eigene Einnahmen oder Klagerechte erfordern aufwendige Verfassungs- und Gesetzesänderungen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=76', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9400, 24, 15, 'MV', 'Einmaliges Baby-Begrüßungsgeld des Landes für Familien mit Hauptwohnsitz im Land, um die Entscheidung für Kinder zu erleichtern.', '{2402}', 9336, 1, 2, null, 'Geldleistungen bei Geburt erhöhen die Geburtenzahl in Studien messbar, aber nur um wenige Prozent; an Alterung und Abwanderung ändern sie wenig, und dauerhafte Landesleistungen sind teuer.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=19', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'belegt', '2026-10-08', false, true, 'blind'),
  (9401, 24, 15, 'MV', 'Landesmittel für Kommunen vorrangig über den allgemeinen Finanzausgleich und die Infrastrukturpauschale statt über zweckgebundene Programme.', '{2404}', 9326, 2, 3, null, 'Kommunen nennen aufwendige Anträge, Nachweise und Personalmangel als Investitionshemmnis; Pauschalen und Verzicht auf Eigenanteile helfen gerade schwachen Kommunen. Dagegen: kein zusätzliches Geld, weniger Steuerung, Wirkung kaum evaluiert.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=57', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9402, 24, 15, 'ST', 'Rückkehrprogramm für ausgewanderte Fachkräfte mit Hilfe bei Wohnung und Kitaplatz sowie Rückkehrprämie nach zwei Jahren Beschäftigung.', '{2401}', 9334, 2, 3, null, 'Rückkehrinitiativen in ländlichen Regionen erhöhen nachweislich die Rückwanderung, besonders bei mittleren und höheren Einkommen; sie wirken auf bereits Abgewanderte und ersetzen fehlende Stellen nicht.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=42', 'https://ideas.repec.org/a/oup/jecgeo/v24y2024i5p759-784..html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9403, 24, 15, 'ST', 'Führerschein-Zuschuss für Auszubildende, gekoppelt an den Ausbildungsabschluss, gegen Abwanderung Jugendlicher.', '{2401}', null, 1, 3, null, 'Ein Führerschein erleichtert Auszubildenden auf dem Land den Weg zu Betrieb und Schule und ist günstig umsetzbar; ein Zuschuss ohne Verbleibsbezug hält kaum jemanden in der Region, Mitnahmeeffekte sind wahrscheinlich.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=147', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9404, 24, 15, 'ST', 'Prämie für Auszubildende mit guten Abschlüssen, ausgezahlt erst nach zwei Jahren Beschäftigung im Land.', '{2401}', 9333, 1, 3, null, 'Bindungsprämien sind einfach einzuführen; Studien zu Verpflichtungsprogrammen finden nur schwache Belege für dauerhaften Verbleib, viele brechen ab oder ziehen nach der Bindungsfrist weg, Mitnahmeeffekte sind wahrscheinlich.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=148', 'https://rrh.org.au/journal/article/2459', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9405, 24, 15, 'ST', 'Landeseigenes Familiengeld, gestaffelt nach Kinderzahl, vor allem für Mehrkindfamilien.', '{2402}', 9336, 1, 2, null, 'Geldleistungen bei Geburt erhöhen die Geburtenzahl in Studien messbar, aber nur um wenige Prozent; an Alterung und Abwanderung ändern sie wenig, und dauerhafte Landesleistungen sind teuer.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=15', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'belegt', '2026-10-08', false, true, 'blind'),
  (9406, 24, 15, 'ST', 'Zinsvergünstigter Kredit für junge Eltern zum Bau oder Kauf von Wohneigentum, mit Teilerlass bei weiteren Geburten.', '{2402}', 9336, 1, 2, null, 'Geldleistungen bei Geburt erhöhen die Geburtenzahl in Studien messbar, aber nur um wenige Prozent; an Alterung und Abwanderung ändern sie wenig, und dauerhafte Landesleistungen sind teuer.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=14', 'https://bse.eu/research/working-papers/effects-universal-child-benefit', 'belegt', '2026-10-08', false, true, 'blind'),
  (9407, 24, 15, 'ST', 'Landeseigene Unterstützung für Kinderwunschbehandlungen, bis der Bund die Kosten übernimmt.', '{2402}', 9338, 1, 3, null, 'Zuschüsse erhöhen die Nutzung der Reproduktionsmedizin und ermöglichen einzelnen Paaren Kinder; Studien finden aber kaum Effekte auf die Geburtenrate insgesamt, weil sich Geburten eher ins höhere Alter verschieben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=14', 'https://ifstudies.org/blog/mandating-insurance-coverage-for-ivf-will-not-boost-fertility', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9408, 24, 15, 'ST', 'Finanzausgleichsgesetz grundlegend reformieren: größere Ausgleichsmasse, mehr Schlüsselzuweisungen, automatischer Konnexitätsausgleich.', '{2404}', 9319, 2, 2, null, 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=232', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9409, 24, 15, 'ST', 'Verbindliche Mindestfinanzausstattung für jede Kommune und Sonderprogramm zum Abbau alter Kassenkredite.', '{2404}', 9319, 2, 2, null, 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=189', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9410, 24, 16, null, 'Strukturpolitik und Infrastrukturinvestitionen, damit Regionen außerhalb der Metropolen attraktiver werden und ländliche Regionen nicht veröden', '{2401}', null, 1, 2, null, 'Regionale Strukturpolitik kann Arbeitsplätze in schwächeren Regionen sichern, wie Evaluationen der Regionalförderung zeigen; die Zusage bleibt aber unbestimmt, ohne Instrument, Ziel oder Betrag.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9411, 24, 16, null, 'Solidarische Ausbildungsumlage: nicht ausbildende Betriebe zahlen in einen Fonds ein, der Ausbildungsplätze und Verbundausbildung finanziert; soll Ausbildung im ländlichen Raum stärken', '{2403}', 9339, 2, 2, null, 'Die Pflege-Ausbildungsumlage erhöhte die Zahl der Auszubildenden; eine Studie aus Québec fand dagegen keine Wirkung auf das Ausbildungsniveau. Mehr Plätze lösen zudem nicht die Passungsprobleme bei unbesetzten Stellen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=46', 'https://dspace-test.bibb.de/items/035ea543-8cab-4e72-a7a6-b31107ba1a2d/full', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9412, 24, 16, null, 'Unternehmen sollen sich im ländlichen Raum finanziell an bezahlbaren Wohnheimplätzen für Auszubildende beteiligen', '{2403}', null, 1, 1, null, 'Mehr Wohnheimplätze auf dem Land erleichtern Auszubildenden den Weg zu entfernten Betrieben; eine Zahlungspflicht für Unternehmen wäre eine verfassungsrechtlich heikle Sonderabgabe und belastet kleine Betriebe.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9413, 24, 16, null, 'Gemeindefinanzreform, volle Anrechnung der Finanzkraft im Länderfinanzausgleich und Altschuldenfonds für überschuldete Kommunen', '{2404}', 9324, 2, 2, null, 'Entschuldung schafft Spielraum, Länderprogramme zeigen gestoppte Kassenkredite, aber auch Investitionskürzungen bei Auflagen; der Bund kann sich finanziell beteiligen, braucht aber die Länder und ggf. eine Verfassungsänderung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9414, 24, 16, 'BE', 'Finanzierungssystem der Bezirke grundlegend ändern, um deren Handlungsfähigkeit durch bedarfsgerechte Ressourcenverteilung zu sichern.', '{2404}', 9321, 1, 2, null, 'Mehr finanzielle Eigenständigkeit kann die Handlungsfähigkeit der Bezirke stärken; die Wirkung hängt von der Gesamtsumme ab, und eigene Einnahmen oder Klagerechte erfordern aufwendige Verfassungs- und Gesetzesänderungen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=263', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9415, 24, 16, 'MV', 'Career-Center an Hochschulen sollen Studierende durch Beratung zu Karriereperspektiven im Land halten.', '{2401}', 9332, 1, 3, null, 'Kontakte zu regionalen Arbeitgebern während des Studiums können den Verbleib erleichtern und sind günstig umsetzbar; ohne passende Stellen bleibt die Wirkung begrenzt und ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=17', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9416, 24, 16, 'MV', 'Kommunale Finanzausstattung stärken und stabilisieren; Gewerbesteuer im Bund zu einer konjunkturunabhängigeren Gemeindewirtschaftssteuer weiterentwickeln.', '{2404}', 9319, 2, 2, null, 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=8', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9417, 24, 16, 'MV', 'Kommunen bei Projektbürokratie und Altschulden entlasten.', '{2404}', 9323, 2, 2, null, 'Länderprogramme haben Kassenkredite gestoppt und Haushalte ausgeglichen; zugleich kürzten Teilnehmerkommunen Investitionen und erhöhten Steuern, und die Programme binden hohe Landesmittel über viele Jahre.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=8', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9418, 24, 16, 'ST', 'Umverteilung zugunsten der Städte und Gemeinden; kommunaler Finanzausgleich stärker dynamisieren und aufgabengerecht gestalten.', '{2404}', 9319, 2, 2, null, 'Mehr allgemeine Zuweisungen erhöhen nachweislich die Ausgaben der Kommunen (Flypaper-Effekt) und setzen direkt an der Finanzlage an; dagegen sprechen knappe Landeshaushalte und dass mehr Geld allein Personal- und Verfahrensengpässe nicht löst.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=79', 'https://www.mohrsiebeck.com/artikel/intergovernmental-transfers-local-fiscal-policy-and-the-flypaper-effect-evidence-from-a-german-state-101628001522116x14462054864882', 'belegt', '2026-10-08', false, true, 'blind'),
  (9419, 24, 16, 'ST', 'Schuldenschnitt für kommunale Altschulden, um Kommunen finanziellen Spielraum zu geben.', '{2404}', null, 2, 1, null, 'Ein Schuldenschnitt schafft verschuldeten Kommunen Spielraum, Entschuldungsprogramme stoppten Kassenkredite, führten aber auch zu Investitionskürzungen; das Land kann ihn auf Bundesebene nur fordern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=79', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9420, 24, 16, 'ST', 'Willkommenszentren als Netzwerk von Kommunen, Initiativen und Behörden zur Aufnahme von Zugewanderten.', '{2402}', null, 1, 3, null, 'Vernetzte Willkommensstrukturen können Zugewanderten das Ankommen und Bleiben erleichtern und sind günstig umsetzbar; sie schaffen selbst keinen Zuzug, die Wirkung auf die Bevölkerungsentwicklung ist kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=98', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9421, 24, 17, null, 'Kommunale Selbstverwaltung stärken, mit einer Altschuldenlösung für die Kommunen.', '{2404}', 9324, 2, 2, null, 'Entschuldung schafft Spielraum, Länderprogramme zeigen gestoppte Kassenkredite, aber auch Investitionskürzungen bei Auflagen; der Bund kann sich finanziell beteiligen, braucht aber die Länder und ggf. eine Verfassungsänderung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9422, 24, 17, null, 'Recht auf einen Ausbildungsplatz für jeden jungen Menschen garantieren.', '{2403}', null, 2, 2, null, 'Ein Rechtsanspruch auf einen Ausbildungsplatz schließt Lücken dort, wo Betriebe fehlen; außerbetriebliche Plätze sind teuer, führen nicht immer in Beschäftigung und lösen unbesetzte Stellen nicht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9423, 24, 17, 'BE', 'Bund soll bei übertragenen Aufgaben die Kosten vollständig tragen; Finanzreform zur Entlastung der Kommunen und mehr Mitsprache der Länder im Bundesrat bei Gesetzen mit finanziellen Folgen.', '{2404}', null, 1, 1, null, 'Volle Kostenübernahme durch den Bund würde Kommunen entlasten; das Land kann sie nur fordern, umsetzbar ist sie nur über Bundesgesetze und das Grundgesetz.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=53', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9424, 24, 17, 'MV', 'Aufgaben, die das Land auf Kommunen überträgt, sollen mit Kostenausgleich verbunden sein.', '{2404}', 9322, 1, 3, null, 'Verhindert neue ungedeckte Lasten und ist in den meisten Landesverfassungen schon angelegt; bestehende Defizite und vom Bund verursachte Sozialausgaben bleiben unberührt, die Wirkung ist empirisch kaum untersucht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=75', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9425, 24, 17, 'MV', 'Pauschale Zuweisungen an Kommunen, auch aus dem Bundes-Sondervermögen, anstelle kleinteiliger Förderprogramme.', '{2404}', 9326, 2, 3, null, 'Kommunen nennen aufwendige Anträge, Nachweise und Personalmangel als Investitionshemmnis; Pauschalen und Verzicht auf Eigenanteile helfen gerade schwachen Kommunen. Dagegen: kein zusätzliches Geld, weniger Steuerung, Wirkung kaum evaluiert.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=76', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9426, 24, 17, 'MV', 'Förderprogramme vereinfachen und auf kommunale Eigenanteile verzichten, wo sie nicht leistbar sind.', '{2404}', 9326, 2, 3, null, 'Kommunen nennen aufwendige Anträge, Nachweise und Personalmangel als Investitionshemmnis; Pauschalen und Verzicht auf Eigenanteile helfen gerade schwachen Kommunen. Dagegen: kein zusätzliches Geld, weniger Steuerung, Wirkung kaum evaluiert.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=76', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9427, 24, 17, 'MV', 'Formulare und Verfahren vereinheitlichen, um den Aufwand der Verwaltungen zu senken.', '{2404}', 9328, 1, 3, null, 'Fristen, Digitalisierung und einfachere Vergabe können Verwaltungen entlasten; bisherige Beschleunigungsgesetze brachten nur begrenzte Erfolge, weil lange Verfahren oft am materiellen Recht und fehlendem Personal liegen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=76', 'https://trid.trb.org/View/2427394', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9428, 24, 17, 'ST', 'Kommunen durch Bund und Land vollständig entschulden, den kommunalen Finanzausgleich stärken und Planungs- und Umsetzungskapazitäten in Verwaltung und Kommunen ausbauen.', '{2404}', 9323, 2, 2, null, 'Länderprogramme haben Kassenkredite gestoppt und Haushalte ausgeglichen; zugleich kürzten Teilnehmerkommunen Investitionen und erhöhten Steuern, und die Programme binden hohe Landesmittel über viele Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=19', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2018/heft/8/beitrag/konsolidierungsprogramme-der-laender-fuer-finanzschwache-kommunen.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9429, 24, 17, 'ST', 'Finanzbeziehungen zwischen Bund, Land und Kommunen reformieren und den kommunalen Anteil an den Steuereinnahmen erhöhen.', '{2404}', 9325, 2, 1, null, 'Ein höherer Steueranteil stärkt die Einnahmebasis dauerhaft; das Land kann das nur über Bundesrat und Bundesgesetz erreichen, und die Verteilung begünstigt eher steuerstarke Kommunen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=76', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9430, 24, 17, 'ST', 'Verwaltung der Kommunen stärken: landeseinheitliche Software, Bürokratieabbau und mehr Serviceorientierung des Landesverwaltungsamts, um lange Genehmigungsverfahren zu verkürzen.', '{2404}', 9328, 1, 3, null, 'Fristen, Digitalisierung und einfachere Vergabe können Verwaltungen entlasten; bisherige Beschleunigungsgesetze brachten nur begrenzte Erfolge, weil lange Verfahren oft am materiellen Recht und fehlendem Personal liegen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=76', 'https://trid.trb.org/View/2427394', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9431, 24, 17, 'ST', 'Mittelzentren als Wohn-, Arbeits- und Versorgungsstandorte stärken (Wohnungsbau, Unternehmensansiedlung, bessere ÖPNV-Anbindung), um Abwanderung zu bremsen.', '{2401}', null, 2, 2, null, 'Wohnungen, Arbeitsplätze und bessere Anbindung in Mittelzentren setzen an Gründen für den Wegzug junger Menschen an; das Paket ist breit, teuer und langfristig, die Wirkung solcher Ankerstrategien ist wenig untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=29', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9432, 24, 17, 'ST', 'Zwei Lehramts-Studienstandorte mit mehr Studienplätzen sichern und allen Absolventen ein Stellenangebot im Schuldienst machen, um Abwanderung zu verhindern.', '{2401}', 9331, 2, 2, null, 'Neue Hochschulen erhöhen nachweislich Studierendenzahl und Anteil Hochqualifizierter in der Region; in wenig dynamischen Regionen wandern Absolventen aber oft ab, und Ausbau kostet viel und dauert Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', 'https://www.zew.de/PU83481', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9433, 24, 18, null, 'Anreize für Unternehmen, Homeoffice-Stellen im ländlichen Raum anzubieten, damit Fachkräfte in der Region bleiben', '{2401}', null, 1, 2, null, 'Homeoffice kann Beschäftigten das Wohnen auf dem Land trotz Stelle in der Stadt ermöglichen; Anreize für Unternehmen sind teuer und ungezielt, und Ausbildung und Berufseinstieg finden selten im Homeoffice statt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=20', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9434, 24, 18, null, 'Gewerbesteuer ersetzen und Konzessionsabgabenverordnung reformieren, um die Finanzen der Kommunen zu stabilisieren', '{2404}', null, 1, 1, null, 'Ein konjunkturunabhängiger Ersatz könnte die Einnahmen stetiger machen; aufkommensneutral bringt er kein zusätzliches Geld, und der Ersatz der Gewerbesteuer erfordert eine Grundgesetzänderung.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=15', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9435, 24, 18, null, 'Demografiefaktor im bundesstaatlichen Finanzausgleich für mehr Verteilungsgerechtigkeit', '{2404}', null, 1, 1, null, 'Ein Demografiefaktor könnte schrumpfenden Ländern und damit indirekt ihren Kommunen mehr Mittel bringen; er braucht eine Einigung aller Länder im Finanzausgleich, und die Wirkung auf die Kommunen ist unsicher.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=16', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9436, 24, 18, null, 'Strukturschwache Regionen sollen lokale Konzepte zur Ansiedlung von Menschen und Gewerbe sowie die Vernetzung von Kommunen fördern können', '{2402}', null, 1, 2, null, 'Lokale Ansiedlungskonzepte können Zuzug von Menschen und Betrieben unterstützen; die Zusage nennt weder Mittel noch Instrument, die Wirkung ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=54', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9437, 24, 18, null, 'Verbundausbildungen und Förderkampagnen helfen Kleinbetrieben und Start-ups, Ausbildungsplätze anzubieten', '{2403}', null, 1, 3, null, 'Verbundausbildung ermöglicht kleinen Betrieben Ausbildung, die sie allein nicht stemmen; als Förderkampagne bleibt der Umfang begrenzt, die Passung von Angebot und Wünschen ändert sich kaum.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=116', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9438, 24, 18, null, 'Digitale Plattformen vernetzen Bildungsträger, Beratungsstellen und Unternehmen für bedarfsgerechte Ausbildungsplanung', '{2403}', null, 1, 3, null, 'Bessere Vernetzung von Trägern, Beratung und Betrieben kann die Ausbildungsplanung verbessern und ist leicht umsetzbar; regionale Passungsprobleme durch Entfernung und Berufswünsche löst eine Plattform allein kaum.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=116', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9439, 24, 18, 'MV', 'Land gleicht neue gesetzliche Pflichten der Kommunen vollständig und dauerhaft finanziell aus.', '{2404}', 9322, 1, 3, null, 'Verhindert neue ungedeckte Lasten und ist in den meisten Landesverfassungen schon angelegt; bestehende Defizite und vom Bund verursachte Sozialausgaben bleiben unberührt, die Wirkung ist empirisch kaum untersucht.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=24', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9440, 24, 18, 'MV', 'Kommunen werden bei der Erstellung von Flächennutzungsplänen unterstützt.', '{2404}', 9329, 1, 3, null, 'Vorlagen und Beratung können kleine, personalschwache Bauverwaltungen entlasten und sind leicht umsetzbar; sie ersetzen weder Personal noch Geld, die Wirkung ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=24', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9441, 24, 18, 'ST', 'Landesweite Rückkehr- und Willkommensprogramme für ehemalige Einwohner*innen, um Abwanderung junger Menschen umzukehren.', '{2401}', 9334, 2, 3, null, 'Rückkehrinitiativen in ländlichen Regionen erhöhen nachweislich die Rückwanderung, besonders bei mittleren und höheren Einkommen; sie wirken auf bereits Abgewanderte und ersetzen fehlende Stellen nicht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=136', 'https://ideas.repec.org/a/oup/jecgeo/v24y2024i5p759-784..html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9442, 24, 18, 'ST', 'Ausbildungs- und Studienangebote im Land ausbauen und eng mit der regionalen Wirtschaft verzahnen.', '{2401}', 9331, 2, 2, null, 'Neue Hochschulen erhöhen nachweislich Studierendenzahl und Anteil Hochqualifizierter in der Region; in wenig dynamischen Regionen wandern Absolventen aber oft ab, und Ausbau kostet viel und dauert Jahre.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=136', 'https://www.zew.de/PU83481', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9443, 24, 18, 'ST', 'Eigenheimförderung für Familien und Rückkehrer sowie günstige kommunale Baugrundstücke in ländlichen Regionen.', '{2401}', 9335, 1, 2, null, 'Wohneigentumsförderung wirkt in ländlichen Regionen als Bleibeanreiz; Evaluationen ähnlicher Zuschüsse zeigen aber erhebliche Mitnahmeeffekte und Vorteile für einkommensstarke Haushalte, die Kosten sind hoch.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=84', 'https://www.diw.de/de/diw_01.c.593685.de/publikationen/diw_aktuell/2018_0014/baukindergeld__einkommensstarke_haushalte_profitieren_in_besonderem_masse.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9444, 24, 18, 'ST', 'Konnexitätsprinzip konsequent umsetzen: Aufgaben, die das Land überträgt, werden finanziert.', '{2404}', 9322, 1, 3, null, 'Verhindert neue ungedeckte Lasten und ist in den meisten Landesverfassungen schon angelegt; bestehende Defizite und vom Bund verursachte Sozialausgaben bleiben unberührt, die Wirkung ist empirisch kaum untersucht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=119', null, 'offen', '2026-10-08', false, true, 'blind');

